const fs=require('fs'),cp=require('child_process');
const fail=m=>{throw new Error(m)};
function replaceOnce(src,needle,repl,label){const i=src.indexOf(needle);if(i<0)fail(`No se encontró ${label}.`);if(src.indexOf(needle,i+1)>=0)fail(`${label} aparece más de una vez.`);return src.slice(0,i)+repl+src.slice(i+needle.length)}
function check(file){const r=cp.spawnSync('node',['--check',file],{encoding:'utf8'});if(r.status!==0)fail(`${file} no compila: ${r.stderr||r.stdout}`)}
let html=fs.readFileSync('index.html','utf8');
if(!html.includes('data-open="artists"')){
 const hymn=/  <button class="exact-card" data-exact-open="hymns" data-open="hymns">.*?<\/button>\n/s.exec(html);if(!hymn)fail('No se encontró tarjeta canónica de Himnos.');
 const card='  <button class="exact-card" data-exact-open="artists" data-open="artists"><span class="exact-illustration"><svg viewBox="0 0 160 150" aria-hidden="true"><circle cx="55" cy="52" r="20" fill="#1b64ad"/><circle cx="105" cy="52" r="20" fill="#d8a52d"/><path d="M25 119c2-28 14-42 30-42s28 14 30 42" fill="#eaf5ff" stroke="#1b64ad" stroke-width="4"/><path d="M75 119c2-28 14-42 30-42s28 14 30 42" fill="#fff7dc" stroke="#d8a52d" stroke-width="4"/><path d="M77 28v31a9 9 0 1 1-5-8V33l24-5v25a9 9 0 1 1-5-8V23z" fill="#0d3e78"/></svg></span><h2>Artistas</h2><p>Cantos agrupados<br>por intérprete</p><span class="exact-mini"><b>♥</b></span></button>\n';
 html=html.slice(0,hymn.index+hymn[0].length)+card+html.slice(hymn.index+hymn[0].length);
}
if(!html.includes('id="artistsView"')){
 const marker='<section id="detail" class="view hidden">';
 const views='<section id="artistsView" class="view hidden"><button class="back" data-home>← Volver</button><div class="section-title-row"><div><h1>🎤 Artistas</h1><p class="muted">Explora los cantos por artista.</p></div></div><div class="search"><input id="artistSearch" placeholder="Buscar artista..." autocomplete="off"></div><div id="artistList" class="list"></div></section>\n<section id="artistSongsView" class="view hidden"><button class="back" id="artistBackBtn">← Artistas</button><div class="head"><h1 id="artistTitle"></h1><p id="artistCount" class="artist"></p></div><div id="artistSongList" class="list"></div></section>\n';
 html=replaceOnce(html,marker,views+marker,'punto de inserción de vistas de Artistas');
}
fs.writeFileSync('index.html',html);
let app=fs.readFileSync('app.js','utf8');
app=replaceOnce(app,"const VIEWS=['home','listing','detail','chordsView','tunerView','calendarView','setlistView']", "const VIEWS=['home','listing','artistsView','artistSongsView','detail','chordsView','tunerView','calendarView','setlistView']",'VIEWS');
const oldRender="function renderSongList(arr,target='songList'){const e=$(target);e.innerHTML=arr.length?arr.map(s=>`<button class=\"song\" data-song=\"${s.id}\"><span class=\"song-main\"><b>${esc(s.title)}</b><br><small class=\"muted\">${esc(s.artist)}</small></span><span class=\"song-actions\"><span class=\"tone\">${esc(displayTone(s.tone))}</span></span></button>`).join(''):`<p class=\"muted\">${appText('Todavía no hay contenido aquí.','There is no content here yet.')}</p>`;e.querySelectorAll('[data-song]').forEach(b=>b.onclick=()=>{songReturn={type:'list',value:lastSongList};openSong(Number(b.dataset.song))})}";
const newRender="function renderSongList(arr,target='songList',returnTo=null){const e=$(target),step=120;if(!e)return;if(!arr.length){e.innerHTML=`<p class=\"muted\">${appText('Todavía no hay contenido aquí.','There is no content here yet.')}</p>`;return}let shown=0;const draw=()=>{e.querySelector('[data-load-more]')?.remove();const part=arr.slice(shown,shown+step),wrap=document.createElement('div');wrap.innerHTML=part.map(s=>`<button class=\"song\" data-song=\"${s.id}\"><span class=\"song-main\"><b>${esc(s.title)}</b><br><small class=\"muted\">${esc(s.artist)}</small></span><span class=\"song-actions\"><span class=\"tone\">${esc(displayTone(s.tone))}</span></span></button>`).join('');[...wrap.children].forEach(n=>{const id=Number(n.dataset.song);n.onclick=()=>{songReturn=returnTo||{type:'list',value:lastSongList};openSong(id)};e.appendChild(n)});shown+=part.length;if(shown<arr.length){const more=document.createElement('button');more.className='btn wide';more.dataset.loadMore='1';more.textContent=appLang()==='en'?`Show more (${arr.length-shown})`:`Mostrar más (${arr.length-shown})`;more.onclick=draw;e.appendChild(more)}};e.innerHTML='';draw()}";
app=replaceOnce(app,oldRender,newRender,'renderSongList canónico');
const artistCode="\nconst artistNorm=s=>String(s||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/&/g,' y ').replace(/[^a-z0-9]+/g,' ').trim();\nconst ARTIST_NAMES=['Alex Campos','Annette Moreno','Blest','Danilo Montero','Doulos','Elevation Worship','Evan Craft','Generación 12','Hillsong','Ingrid Rosario','Jaime Murrell','Jesús Adrián Romero','Jonathan & Sarah Jerez','La IBI','Living','Majo y Dan','Marcela Gándara','Marco Barrientos','Marcos Brunet','Marcos Witt','Para Su Gloria','Roberto Orellana','Rojo','Samuel Adrián','Satélite','Tercer Cielo','Twice','Un Corazón','Veinte Veinte','Sarai Rivera','Gadiel Espinoza','En Espíritu y en Verdad'];\nconst ARTIST_ALIAS=(()=>{const m=new Map(ARTIST_NAMES.map(x=>[artistNorm(x),x]));m.set('adoracion la ibi','La IBI');m.set('de la ibi','La IBI');m.set('hillsong en espanol','Hillsong');return m})();\nconst canonicalArtist=a=>ARTIST_ALIAS.get(artistNorm(a))||null;\nfunction artistGroups(){const m=new Map;for(const s of songs){if(s.type!=='cantos')continue;const a=canonicalArtist(s.artist);if(!a)continue;if(!m.has(a))m.set(a,[]);m.get(a).push(s)}return [...m.entries()].sort((a,b)=>a[0].localeCompare(b[0],appLocale(),{sensitivity:'base'}))}\nfunction showArtists(){showView('artistsView');$('artistSearch').value='';$('artistSearch').oninput=renderArtists;renderArtists()}\nfunction renderArtists(){const q=artistNorm($('artistSearch')?.value||''),groups=artistGroups().filter(([a])=>!q||artistNorm(a).includes(q));$('artistList').innerHTML=groups.length?groups.map(([a,list])=>`<button class=\"song\" data-artist-name=\"${esc(a)}\"><span class=\"song-main\"><b>${esc(a)}</b><br><small class=\"muted\">${list.length} ${appLang()==='en'?'songs':'cantos'}</small></span><span class=\"exact-chevron\">›</span></button>`).join(''):`<p class=\"muted\">${appText('No se encontraron artistas.','No artists found.')}</p>`;$('artistList').querySelectorAll('[data-artist-name]').forEach(b=>b.onclick=()=>showArtist(b.dataset.artistName))}\nfunction showArtist(name){const arr=songs.filter(s=>s.type==='cantos'&&canonicalArtist(s.artist)===name).sort((a,b)=>a.title.localeCompare(b.title,appLocale(),{sensitivity:'base'}));showView('artistSongsView');$('artistTitle').textContent=name;$('artistCount').textContent=arr.length+' '+(appLang()==='en'?'songs':'cantos');renderSongList(arr,'artistSongList',{type:'artist',value:name})}\n";
app=replaceOnce(app,"function showSongList(type){",artistCode+"function showSongList(type){",'inserción de funciones Artistas');
app=replaceOnce(app,"function songBack(){if(songReturn.type==='setlist')showEventSetlist(songReturn.value);else if(songReturn.type==='home')home();else showSongList(songReturn.value||'cantos')}","function songBack(){if(songReturn.type==='setlist')showEventSetlist(songReturn.value);else if(songReturn.type==='home')home();else if(songReturn.type==='artist')showArtist(songReturn.value);else showSongList(songReturn.value||'cantos')}",'songBack');
app=replaceOnce(app,"function navigate(d){if(d==='home')home();else if(d==='songs')showSongList('cantos');else if(d==='hymns')showSongList('himnos');else if(d==='favorites'){lastSongList='fav';showSongList('fav')}else if(d==='chords')showChords();else if(d==='tuner')showTuner();else if(d==='calendar')showCalendar()}","function navigate(d){if(d==='home')home();else if(d==='songs')showSongList('cantos');else if(d==='hymns')showSongList('himnos');else if(d==='artists')showArtists();else if(d==='favorites'){lastSongList='fav';showSongList('fav')}else if(d==='chords')showChords();else if(d==='tuner')showTuner();else if(d==='calendar')showCalendar()}",'navigate');
app=replaceOnce(app,"function renderEventSongChoices(){const q=$('eventSongSearch').value.trim().toLowerCase(),a=songs.filter(s=>(s.title+' '+s.artist).toLowerCase().includes(q));$('eventSongChoices').innerHTML=a.map(s=>`<label class=\"choice-row\"><input type=\"checkbox\" data-choice-song=\"${s.id}\" ${editingSetlist.some(x=>x.songId===s.id)?'checked':''}><span><b>${esc(s.title)}</b><br><small class=\"muted\">${esc(s.artist)} · ${esc(displayTone(s.tone))}</small></span></label>`).join('');$('eventSongChoices').querySelectorAll('[data-choice-song]').forEach(c=>c.onchange=()=>{const id=Number(c.dataset.choiceSong),s=songs.find(x=>x.id===id);if(c.checked&&!editingSetlist.some(x=>x.songId===id))editingSetlist.push({songId:id,tone:s.tone});if(!c.checked)editingSetlist=editingSetlist.filter(x=>x.songId!==id);renderSelectedSetlist()})}","function renderEventSongChoices(){const q=$('eventSongSearch').value.trim().toLowerCase(),all=songs.filter(s=>(s.title+' '+s.artist).toLowerCase().includes(q)),a=all.slice(0,q?180:80);$('eventSongChoices').innerHTML=a.map(s=>`<label class=\"choice-row\"><input type=\"checkbox\" data-choice-song=\"${s.id}\" ${editingSetlist.some(x=>x.songId===s.id)?'checked':''}><span><b>${esc(s.title)}</b><br><small class=\"muted\">${esc(s.artist)} · ${esc(displayTone(s.tone))}</small></span></label>`).join('')+(all.length>a.length?`<p class=\"muted\">${appText('Escribe más del título o artista para afinar la búsqueda.','Type more of the title or artist to refine the search.')}</p>`:'');$('eventSongChoices').querySelectorAll('[data-choice-song]').forEach(c=>c.onchange=()=>{const id=Number(c.dataset.choiceSong),s=songs.find(x=>x.id===id);if(c.checked&&!editingSetlist.some(x=>x.songId===id))editingSetlist.push({songId:id,tone:s.tone});if(!c.checked)editingSetlist=editingSetlist.filter(x=>x.songId!==id);renderSelectedSetlist()})}",'renderEventSongChoices');
app=replaceOnce(app,"$('songBackBtn').onclick=songBack;","$('songBackBtn').onclick=songBack;$('artistBackBtn').onclick=showArtists;",'wire artistBackBtn');
fs.writeFileSync('app.js',app);check('app.js');
console.log('Artistas integrado directamente en index.html y app.js.');
